DO $$
DECLARE
  rec RECORD;
  cur_status VARCHAR(30);
  cur_clinician INT;
BEGIN
  FOR rec IN SELECT * FROM visit_events ORDER BY event_id LOOP
    SELECT status, assigned_clinician_id INTO cur_status, cur_clinician FROM visit_slots WHERE slot_id = rec.slot_id;
    IF rec.event_type = 1 AND cur_status = 'open' THEN
      UPDATE visit_slots SET status = 'scheduled', assigned_clinician_id = rec.clinician_id WHERE slot_id = rec.slot_id;
    ELSIF rec.event_type = 2 AND cur_status = 'scheduled' AND cur_clinician = rec.clinician_id THEN
      UPDATE visit_slots SET status = 'completed' WHERE slot_id = rec.slot_id;
    ELSIF rec.event_type = 3 AND cur_status = 'completed' THEN
      UPDATE visit_slots SET status = 'followup_scheduled', assigned_clinician_id = rec.clinician_id WHERE slot_id = rec.slot_id;
    END IF;
  END LOOP;
END $$;
SELECT * FROM visit_slots ORDER BY slot_id;

