/* notes */

DO $$
DECLARE
    r RECORD;
    c_status VARCHAR;
    c_assigned_clinician_id INT;
BEGIN
    FOR r IN SELECT * FROM visit_events ORDER BY event_id LOOP
        SELECT status, assigned_clinician_id INTO c_status, c_assigned_clinician_id
        FROM visit_slots
        WHERE slot_id = r.slot_id;

        IF r.event_type = 1 AND c_status = 'open' THEN
            UPDATE visit_slots
            SET status = 'scheduled',
                assigned_clinician_id = r.clinician_id
            WHERE slot_id = r.slot_id;

        ELSIF r.event_type = 2 AND c_status = 'scheduled' AND c_assigned_clinician_id = r.clinician_id THEN
            UPDATE visit_slots
            SET status = 'completed'
            WHERE slot_id = r.slot_id;

        ELSIF r.event_type = 3 AND c_status = 'completed' THEN
            UPDATE visit_slots
            SET status = 'followup_scheduled',
                assigned_clinician_id = r.clinician_id
            WHERE slot_id = r.slot_id;

        END IF;
    END LOOP;
END $$;

SELECT * FROM visit_slots ORDER BY slot_id;
